<?php require_once __DIR__.'/includes/bootstrap.php';require_login();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id||(int)$id===(int)$_SESSION['user_id'])redirect('/profile.php');$s=$pdo->prepare('SELECT id,full_name,email,profile_picture,created_at FROM users WHERE id=?');$s->execute([$id]);$user=$s->fetch();if(!$user){flash('error','User not found.');redirect('/search.php');}$page_title='Member profile';require __DIR__.'/includes/header.php'; ?><section class="panel public-profile"><img src="<?= avatar($user) ?>" alt="Profile picture"><div><span class="eyebrow">EVENTPRO MEMBER</span><h1><?= e($user['full_name']) ?></h1><p><?= e($user['email']) ?></p><small>Member since <?= e(date('d M Y',strtotime($user['created_at']))) ?></small><div class="actions"><a class="button primary" href="conversation.php?user_id=<?= (int)$user['id'] ?>">Send Message</a><a class="button" href="search.php">Back to Search</a></div></div></section><?php require __DIR__.'/includes/footer.php'; ?>